[asy]
unitsize(1.5 cm);

pair D = (4,-3), V = (2,1), P = (V + reflect((0,0),D)*(V))/2;

draw((4,-3)/2--(-4,3)/2,dashed);
draw((-2,0)--(2,0));
draw((0,-2)--(0,2));
draw((0,0)--P,Arrow(6));

label("$\ell$", (4,-3)/2, SE);
[/asy]

